(()=>{'use strict';
const PREVIEW=window.RS_PREVIEW===true;
const BRAND=PREVIEW?(window.RS_PREVIEW_BRAND||'/assets/brand-wordmark.webp'):'/assets/brand-wordmark.webp';
const BRAND_ICON=PREVIEW?(window.RS_PREVIEW_ICON||'/assets/refills-icon.png'):'/assets/refills-icon.png';
const $=id=>document.getElementById(id);
const icon=name=>`<svg class="icon" aria-hidden="true"><use href="#icon-${name}"></use></svg>`;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=x=>Number(x||0).toLocaleString('es-ES',{maximumFractionDigits:2});
const usdt=x=>Number(x||0).toLocaleString('es-ES',{minimumFractionDigits:2,maximumFractionDigits:2});
const safeURL=x=>/^https:\/\/[^\s<>"']+$/i.test(String(x||''))?x:'';
const asset=(name)=>PREVIEW?(window.RS_PREVIEW_ASSETS?.[name]||'/assets/'+name):'/assets/'+name;
const assetSrc=(name)=>asset(name);
window.addEventListener('error',(event)=>{const im=event.target;if(!(im instanceof HTMLImageElement)||im.dataset.fallbackDone)return;if(im.dataset.coverId){im.dataset.fallbackDone='1';im.src=asset((LOCAL_CATALOG_GAMES.some(g=>g.id===im.dataset.coverId)?im.dataset.coverId:'fallback')+'.svg');}else if(im.dataset.localFallback){im.dataset.fallbackDone='1';im.src=asset(im.dataset.localFallback);}},true);

const S={ready:false,store:null,route:location.pathname,google:false,client:null,user:null,profile:null,member:false,wallet:null,expiry:null,orders:[],admin:false,adminOrders:[],planRequests:[],apiProducts:[],adminCustomers:[],adminAllOffers:[],adminFulfillments:[],adminOverview:null,selectedProvider:'centralone',gameId:null,offerId:null,step:1,playerId:'',zoneId:'',payment:'mobile',sourcePhone:'',targetPayload:{},proof:null,proofName:'',requestId:null,lastOrder:null,selectedOrder:null,filter:'all',search:'',admSearch:'',storeError:null,guestEntered:false,phoneRegister:true,customerScanInitialized:false};
const LOCAL_CATALOG_GAMES=[{id:'free-fire',name:'Free Fire',tag:'Battle Royale',featured:true,sortOrder:1},{id:'roblox',name:'Roblox',tag:'Plataformas',featured:true,sortOrder:2},{id:'mobile-legends',name:'Mobile Legends',tag:'MOBA',featured:true,sortOrder:3},{id:'pubg',name:'PUBG Mobile',tag:'Battle Royale',featured:false,sortOrder:4},{id:'cod',name:'Call of Duty Mobile',tag:'Acción',featured:false,sortOrder:5},{id:'honor',name:'Honor of Kings',tag:'MOBA',featured:false,sortOrder:6}];
const LOCAL_CATALOG_OFFERS=[];
const LOCAL_VIEW_STORE={live:false,games:LOCAL_CATALOG_GAMES,offers:LOCAL_CATALOG_OFFERS,config:{buySmPerUsdt:350,cupPerSm:3,cardFee:5,mobilePhone:'50237996',walletPhone:'',cardNumber:'9204-1299-7870-3553',confirmPhone:'50237996',planPrice:null,planDays:30}};
function notify(msg){
 const host=$('toasts');if(!host)return;
 const alertType=/error|fall[oó]|incorrect|advert|no se pudo|falta|inv[aá]l|requiere|caduc|conexi[oó]n|rechaz|indisponib|pendiente|todav[ií]a|no est[aá]/i.test(String(msg));
 host.innerHTML=`<div class="toast ${alertType?'toast-alert':'toast-ok'}" role="${alertType?'alert':'status'}"><span class="toast-symbol" aria-hidden="true">${icon(alertType?'shield':'check')}</span><div class="toast-message"><strong>${alertType?'Aviso de Refills Shop':'Refills Shop'}</strong><p>${esc(msg)}</p></div><button class="toast-close" type="button" aria-label="Cerrar aviso" title="Cerrar">${icon('x')}</button></div>`;
 clearTimeout(notify.timer);notify.timer=setTimeout(()=>{host.innerHTML=''},5500);
 host.querySelector('.toast-close')?.addEventListener('click',()=>{clearTimeout(notify.timer);host.innerHTML=''},{once:true});
}
function err(msg){notify(msg);}
const checkoutPaths={1:'/compra/datos',2:'/compra/pago',3:'/compra/revision',4:'/compra/listo'};
function canonical(path){if(path==='/inicio')return '/';if(path==='/catalogo')return '/catalog';if(path==='/pedidos')return '/orders';if(path==='/revendedores')return '/reseller';if(path==='/cuenta'||path==='/iniciar-sesion'||path==='/crear-cuenta')return '/account';if(path.startsWith('/juegos/'))return '/games/'+path.slice(8);if(path.startsWith('/compra/'))return '/checkout';return path;}
function hydratePath(path){S.route=canonical(path);if(path==='/inicio'||S.route==='/catalog')S.guestEntered=true;const index=Object.values(checkoutPaths).indexOf(path);if(index!==-1){S.step=index+1;if(S.step>1&&!S.playerId)S.step=1;if(S.step>2&&!S.proof&&S.step!==4)S.step=2;}}
function route(path){hydratePath(path);try{if(PREVIEW){const previewUrl=new URL(location.href);previewUrl.searchParams.set('ruta',path);history.pushState({ruta:path},'',previewUrl.href)}else history.pushState({ruta:path},'',path)}catch{}S.search='';window.scrollTo({top:0,behavior:'instant'});render();if(S.route==='/orders')loadOrders();if(S.route==='/admin/orders')loadAdminOrders();if(S.route==='/admin/resellers')loadPlanRequests();if(S.route==='/admin/customers'||S.route==='/admin')loadCustomers();if(S.route==='/admin/fulfillment'){loadAdminOrders();loadFulfillments()}if(S.route==='/admin/offers')loadAdminAllOffers();if(S.route==='/admin/integrations')loadAdminOverview();}
window.addEventListener('popstate',()=>{hydratePath(PREVIEW?(new URLSearchParams(location.search).get('ruta')||'/'):location.pathname);render()});
function game(id){return S.store?.games.find(g=>g.id===id)}
function offers(id){return S.store?.offers.filter(o=>o.gameId===id)||[]}
try{const draft=JSON.parse(sessionStorage.getItem('rs_v6_selected_offer')||'null');if(draft&&/^[a-z0-9-]{2,60}$/.test(draft.gameId)&&/^[0-9a-f-]{36}$/i.test(draft.offerId)){S.gameId=draft.gameId;S.offerId=draft.offerId;}}catch{}
function selection(){return {g:game(S.gameId),o:S.store?.offers.find(o=>o.id===S.offerId)}}
function coverSrc(g){const id=LOCAL_CATALOG_GAMES.some(v=>v.id===g?.id)?g.id:'fallback';return safeURL(g?.imageUrl)||asset(id+'.svg')}
function cover(g){return `<div class="game-cover"><img src="${esc(coverSrc(g))}" data-cover-id="${esc(g.id)}" alt="${esc(g.name)}" decoding="async"><span class="game-tag">${esc(g.tag||'Juegos')}</span><span class="game-name">${esc(g.name)}</span></div>`}
function pagehead(k,title,sub=''){return `<header class="pagehead"><div class="caps">${esc(k)}</div><h1>${esc(title)}</h1>${sub?`<p>${esc(sub)}</p>`:''}</header>`}
function customerPrices(o){return `<div class="currency-grid"><div class="currency-box"><small>SALDO SM</small><strong>${money(o.sm)}</strong></div><div class="currency-box"><small>CUP</small><strong>${money(o.cup)}</strong></div><div class="currency-box"><small>USDT</small><strong>${usdt(o.usdt)}</strong></div></div>`}
function cards(games){return `<div class="game-grid">${games.map(g=>{const list=offers(g.id),from=list.length?`Desde ${money(Math.min(...list.map(x=>x.sm)))} SM`:'Consultar disponibilidad';return `<article class="card game-card" data-href="/juegos/${encodeURIComponent(g.id)}">${cover(g)}<div class="game-content"><div class="game-metadata"><span class="game-count">${list.length} ${list.length===1?'oferta':'ofertas'}</span><span class="game-online">CATÁLOGO DIGITAL</span></div><h3>${esc(g.name)}</h3><p>${esc(from)}</p><button class="btn btn-primary" data-href="/juegos/${encodeURIComponent(g.id)}" type="button">Ver ofertas →</button></div></article>`}).join('')}</div>`}
function home(){const featured=S.store.games.filter(g=>g.featured).sort((a,b)=>(a.sortOrder||0)-(b.sortOrder||0)).slice(0,3);const list=featured.length?featured:S.store.games.slice(0,3);return `<section class="hero hero-next"><div class="hero-copy"><div class="caps">REFILLS SHOP · RECARGAS DIGITALES</div><h1>Recargas <span class="hero-blue">sin fronteras</span></h1><p>Explora juegos desde cualquier país. El pago está disponible por los métodos habilitados para cada región; por ahora, las transferencias se procesan en Cuba.</p><div class="hero-actions"><button class="btn btn-primary" data-href="/catalogo">Ver catálogo ${icon('arrow')}</button><button class="btn btn-ghost" data-href="/pedidos">Mis pedidos</button></div></div><div class="hero-side"><div class="hero-benefit"><span class="hero-benefit-graphic">${icon('game')}</span><span><small>CATÁLOGO DIGITAL</small><strong>Encuentra tu juego favorito</strong><span>Ofertas organizadas por juego</span></span></div><button type="button" class="hero-search" data-href="/catalogo" aria-label="Abrir buscador de juegos">${icon('search')} <span>Buscar un juego...</span>${icon('arrow')}</button></div></section><section class="mt"><div class="section-head"><div><div class="caps">DESTACADOS</div><h2>Juegos populares</h2></div></div>${cards(list)}<div class="more-catalog"><button class="btn btn-outline" data-href="/catalogo">Explorar todos los juegos ${icon('arrow')}</button></div></section><section class="card pad mt howto"><div class="caps">COMPRA SIN COMPLICACIONES</div><h2 class="section-title">Cómo funciona</h2><div class="howto-grid"><span><b>01</b> Elige tu juego</span><span><b>02</b> Completa tus datos</span><span><b>03</b> Adjunta tu pago</span><span><b>04</b> Sigue tu pedido</span></div></section>`}
function catalog(){const list=S.store.games.filter(g=>(g.name+' '+g.tag).toLowerCase().includes(S.search.toLowerCase()));return `${pagehead('CATÁLOGO','Todos los juegos','Selecciona tu juego para consultar las ofertas y precios finales.')}<label class="search-field mb"><span aria-hidden="true">${icon('search')}</span><input id="searchGames" type="search" aria-label="Buscar juegos" placeholder="Buscar Free Fire, Roblox, PUBG..." value="${esc(S.search)}"></label>${list.length?cards(list):`<section class="card empty"><h3>No encontramos ese juego</h3><p>Prueba con otro nombre.</p></section>`}`}
function targetSchema(o){return Array.isArray(o?.targetSchema)?o.targetSchema.filter(f=>/^[a-z0-9_]{1,50}$/i.test(String(f.key||''))):[]}
function targetForm(o){const fields=targetSchema(o);if(!fields.length)return `<div class="field"><label>ID de jugador / cuenta</label><input name="playerId" required minlength="3" maxlength="80" autocomplete="off" value="${esc(S.playerId)}" placeholder="Tu ID de jugador"></div><div class="field"><label>Servidor / zona (si aplica)</label><input name="zoneId" maxlength="30" value="${esc(S.zoneId)}" placeholder="Opcional"></div>`;
return fields.map(field=>`<div class="field"><label>${esc(field.label||field.key)}</label>${field.type==='select'?`<select name="target_${esc(field.key)}" required><option value="">Selecciona una opción</option>${(field.options||[]).map(x=>`<option value="${esc(x.value)}" ${S.targetPayload[field.key]===x.value?'selected':''}>${esc(x.label||x.value)}</option>`).join('')}</select>`:`<input name="target_${esc(field.key)}" required maxlength="64" autocomplete="off" value="${esc(S.targetPayload[field.key]||'')}" placeholder="${esc(field.label||field.key)}">`}</div>`).join('')}
function gamePage(id){const g=game(id);if(!g)return `${pagehead('JUEGO NO ENCONTRADO','Este juego ya no está disponible')}<button class="btn btn-outline" data-href="/catalogo">Volver al catálogo</button>`;const products=offers(id);return `${pagehead(g.tag,g.name,'Precios de referencia en SM, CUP y USDT. Los métodos de pago disponibles actualmente operan en Cuba.')}<div class="offer-grid">${products.map(o=>`<article class="card offer-card"><img class="offer-cover" src="${esc(coverSrc(g))}" data-cover-id="${esc(g.id)}" alt="${esc(g.name)}" decoding="async"><div class="offer-content"><div class="offer-eyebrow"><span class="offer-live-dot"></span> RECARGA DISPONIBLE</div><h3>${esc(o.name)}</h3>${customerPrices(o)}${o.inStock===false?'<span class="state-pill rejected">Agotado temporalmente</span>':`<button class="btn btn-primary" data-buy="${esc(o.id)}" data-game="${esc(g.id)}">Elegir oferta →</button>`}</div></article>`).join('')}</div>${!products.length?`<div class="card empty"><h3>Sin ofertas publicadas</h3><p>Pronto estarán disponibles. Solo mostramos recargas activas.</p></div>`:''}<div class="mt"><button class="btn btn-ghost" data-href="/catalogo">← Volver al catálogo</button></div>`}
function steps(){return `<div class="stepper">${['Datos','Pago','Revisión','Listo'].map((x,i)=>`<div class="step ${i+1===S.step?'active':i+1<S.step?'done':''}">${i+1} · ${x}</div>`).join('')}</div>`}
function payAmount(){const {o}=selection();if(!o)return {amount:0,currency:'CUP'};return S.payment==='mobile'?{amount:o.sm,currency:'SM'}:{amount:S.payment==='card'?o.card:o.cup,currency:'CUP'}}
function paymentName(id){return ({mobile:'ETECSA · Saldo móvil',wallet:'MiTransfer · Monedero',card:'Transfermóvil · CUP'})[id]||id}
function sumBox(){const {g,o}=selection();if(!g||!o)return '';const amt=payAmount();return `<aside class="card checkout-summary"><div class="summary-top"><span class="caps">RESUMEN DEL PEDIDO</span><strong>${money(amt.amount)} ${esc(amt.currency)}</strong></div><div class="sum-row"><span>Juego / oferta</span><strong>${esc(g.name)} · ${esc(o.name)}</strong></div>${S.playerId?`<div class="sum-row"><span>ID del jugador</span><strong>${esc(S.playerId)}</strong></div>`:''}<div class="sum-row"><span>Método</span><strong>${esc(paymentName(S.payment))}</strong></div></aside>`}
function recipient(label,value){return `<div class="recipient"><div><small>${esc(label)}</small><strong>${esc(value)}</strong></div><button class="btn btn-outline btn-sm" type="button" data-copy="${esc(value)}">Copiar</button></div>`}
function paymentFields(){const c=S.store.config;let instructions='';if(S.payment==='mobile')instructions=`<div class="notice">Transfiere <strong>${money(payAmount().amount)} SM</strong> a este teléfono.</div>${recipient('Saldo móvil destino',c.mobilePhone)}<div class="field"><label>Número desde el que transferiste</label><input id="originPhone" type="tel" inputmode="numeric" maxlength="8" required pattern="[0-9]{8}" placeholder="Tu número de ocho dígitos" value="${esc(S.sourcePhone)}"></div>`;
if(S.payment==='wallet')instructions=c.walletPhone?`<div class="notice">Transfiere <strong>${money(payAmount().amount)} CUP</strong> a MiTransfer. No es necesario indicar el número de origen.</div>${recipient('Monedero MiTransfer',c.walletPhone)}`:'<div class="notice warn">MiTransfer todavía no tiene un número de destino configurado.</div>';
if(S.payment==='card')instructions=`<div class="notice">Transfiere <strong>${money(payAmount().amount)} CUP</strong> a la tarjeta e indica este número para confirmación.</div>${recipient('Número de tarjeta',c.cardNumber)}${recipient('Número de confirmación',c.confirmPhone)}`;
return `<div class="fields">${instructions}<label class="upload">${icon('image')} <strong>Adjunta tu comprobante</strong><small>JPG, PNG o WEBP · Máximo 3 MB</small><input id="proofFile" type="file" accept="image/png,image/jpeg,image/webp" ${S.proof?'':'required'}>${S.proof?'<small>Captura seleccionada: '+esc(S.proofName)+'</small>':''}</label></div>`}
function checkout(){const {g,o}=selection();if(!g||!o)return `${pagehead('COMPRA','Selecciona una oferta primero')}<button class="btn btn-primary" data-href="/catalogo">Ver juegos</button>`;if(!S.user&&!PREVIEW)return `${pagehead('PASO PREVIO','Inicia sesión para comprar','El catálogo puede explorarse libremente; inicia sesión para enviar pedidos.')}<button class="btn btn-primary" data-href="/cuenta">Continuar</button>`;if(S.user&&!S.profile)return profilePage(true);
const info=S.step===1?'Datos de recarga':S.step===2?'¿Cómo deseas pagar?':S.step===3?'Comprueba tu pedido':'Solicitud enviada';
let form='';if(S.step===1)form=`<form id="playerForm" class="fields"><h2>Datos de tu juego</h2><p class="muted small">Completa solo los datos que este producto necesita. Verifica tu cuenta antes del pago.</p>${targetForm(o)}<button type="submit" class="btn btn-primary btn-wide">Continuar al pago →</button></form>`;
if(S.step===2)form=`<form id="paymentForm" class="fields"><h2>Métodos de pago disponibles en Cuba</h2><p class="muted small">Aún no aceptamos pagos internacionales. Consulta las opciones antes de enviar un pedido.</p><div class="payment-methods">${[['mobile','etecsa.svg','Saldo móvil','ETECSA · Saldo móvil'],['wallet','mitransfer.svg','MiTransfer','Monedero · MiTransfer'],['card','transfermovil.svg','Transferencia CUP','Tarjeta · Transfermóvil']].map(([key,asset,label,sub])=>`<label class="payment-option"><input type="radio" name="payment" value="${key}" ${S.payment===key?'checked':''}><span class="payment-symbol payment-${key}"><img src="${esc(assetSrc(asset))}" data-local-fallback="${esc(asset)}" alt=""></span><span class="payment-copy"><strong>${label}</strong><small>${sub}</small></span></label>`).join('')}</div><div id="paymentDynamic">${paymentFields()}</div><div class="btn-row"><button type="button" class="btn btn-ghost" data-step="1">← Atrás</button><button type="submit" class="btn btn-primary">Revisar pedido →</button></div></form>`;
if(S.step===3)form=`<div class="fields"><h2>Revisión final</h2><div class="sum-row"><span>Juego</span><strong>${esc(g.name)}</strong></div><div class="sum-row"><span>Oferta</span><strong>${esc(o.name)}</strong></div><div class="sum-row"><span>ID del jugador</span><strong>${esc(S.playerId)}</strong></div><div class="sum-row"><span>Método</span><strong>${esc(paymentName(S.payment))}</strong></div><div class="sum-row"><span>Captura</span><strong>${esc(S.proofName)}</strong></div><div class="notice warn">La transferencia se revisará manualmente. Enviar esta solicitud no confirma todavía una recarga.</div><label class="checkbox-line"><input id="confirmOrder" type="checkbox"> Confirmo que los datos y el importe son correctos.</label><div class="btn-row"><button class="btn btn-ghost" data-step="2">← Corregir</button><button class="btn btn-primary" id="sendOrder">Enviar solicitud →</button></div></div>`;
if(S.step===4&&S.lastOrder){const o=S.lastOrder;form=`<section class="done-card"><div class="caps">PEDIDO REGISTRADO</div><h2>¡Solicitud enviada!</h2><p class="muted">Guarda este código. Tu recarga está pendiente de revisión manual.</p><span class="done-code">${esc(o.code)}</span><span class="state-pill pending">Pendiente</span><div class="btn-row mt"><button class="btn btn-ghost" data-copy="${esc(o.code)}">Copiar código</button><button class="btn btn-primary" data-href="/pedidos">Ver mis pedidos →</button></div></section>`}
return `<section class="checkout">${pagehead('COMPRA · '+esc(g.name),info,'Una pantalla por paso, sin datos amontonados.')}${steps()}<div class="card checkout-form">${form}</div>${S.step<=3?sumBox():''}</section>`}
const COUNTRY_OPTIONS=[['+53','Cuba +53'],['+1','EE. UU. / Canadá +1'],['+52','México +52'],['+57','Colombia +57'],['+58','Venezuela +58'],['+34','España +34'],['+54','Argentina +54'],['+55','Brasil +55'],['+56','Chile +56'],['+51','Perú +51'],['+593','Ecuador +593'],['+507','Panamá +507'],['+1','Rep. Dominicana / Caribe +1'],['+44','Reino Unido +44'],['+33','Francia +33'],['+49','Alemania +49'],['+39','Italia +39'],['+351','Portugal +351'],['+91','India +91'],['+86','China +86'],['+81','Japón +81'],['+971','Emiratos +971'],['+598','Uruguay +598'],['+595','Paraguay +595'],['+591','Bolivia +591'],['+506','Costa Rica +506'],['+503','El Salvador +503'],['+502','Guatemala +502'],['+504','Honduras +504'],['+505','Nicaragua +505'],['+509','Haití +509'],['+41','Suiza +41'],['+31','Países Bajos +31'],['+32','Bélgica +32'],['+353','Irlanda +353'],['+61','Australia +61'],['+64','Nueva Zelanda +64'],['+81','Japón +81']];
function internationalPhoneFromForm(f){const code=String(f.elements.countryCode?.value||'').trim();const local=String(f.elements.phone?.value||'').replace(/[^0-9]/g,'');if(!/^\+[1-9][0-9]{0,2}$/.test(code)||local.length<5||local.length>12)throw Error('Introduce un prefijo internacional y un teléfono válido.');if(code==='+53'&&!/^5[0-9]{7}$/.test(local))throw Error('Para Cuba, escribe 8 dígitos y empieza por 5.');if(code==='+1'&&local.length!==10)throw Error('Para +1, escribe un número de 10 dígitos.');const digits=code.slice(1)+local;if(digits.length<8||digits.length>15)throw Error('Revisa el número y el prefijo internacional.');return code+local}
function aliasForInternationalPhone(phone){const digits=String(phone).replace(/[^0-9]/g,'');return (digits.startsWith('53')&&digits.length===10?'cu':'tel')+digits+'@refillshop.pages.dev'}
function authWelcome(){const registering=S.phoneRegister;return `<section class="auth-shell"><div class="auth-content auth-clean"><div class="auth-top"><span class="auth-line"></span><span class="caps">ACCESO SEGURO</span></div><h1>${registering?'Crea tu':'Entra a tu'} <span>cuenta</span></h1><p class="auth-lead">Regístrate desde cualquier país con tu teléfono y contraseña. No necesitas un correo electrónico.</p><div class="phone-auth-switch"><button type="button" id="chooseRegister" class="${registering?'active':''}">Crear cuenta</button><button type="button" id="chooseLogin" class="${!registering?'active':''}">Iniciar sesión</button></div><form id="phoneAuthForm" class="fields phone-auth-form">${registering?`<div class="field"><label for="phoneName">Nombre completo</label><input id="phoneName" name="fullName" autocomplete="name" minlength="2" maxlength="90" required placeholder="Tu nombre"></div>`:''}<div class="field"><label for="countryCode">País o prefijo internacional</label><select id="countryCode" name="countryCode" required class="phone-country-select"><option value="" disabled selected>Selecciona tu país</option>${COUNTRY_OPTIONS.map(([val,label])=>`<option value="${esc(val)}">${esc(label)}</option>`).join('')}</select><p class="muted small">Selecciona el país donde está registrado tu número.</p></div><div class="field"><label for="phoneNumber">Número de teléfono (sin prefijo)</label><input id="phoneNumber" name="phone" type="tel" inputmode="tel" autocomplete="tel-national" minlength="5" maxlength="18" required placeholder="Tu número de teléfono"></div><div class="field"><label for="phonePassword">Contraseña</label><input id="phonePassword" name="password" type="password" autocomplete="${registering?'new-password':'current-password'}" minlength="${registering?'10':'1'}" maxlength="72" required placeholder="${registering?'Al menos 10 caracteres, letras y números':'Tu contraseña'}"></div>${registering?`<input class="honeypot" name="website" tabindex="-1" autocomplete="off" aria-hidden="true"><p class="auth-hint auth-hint-compact">El registro no requiere SMS. Tu número no se verificará automáticamente. El equipo puede contactarte por WhatsApp o SMS para confirmar el registro. Conserva tu contraseña: no hay recuperación automática por teléfono.</p>`:''}<button type="submit" class="btn btn-primary btn-wide" ${PREVIEW?'disabled':''}>${registering?'Crear mi cuenta':'Entrar a mi cuenta'}</button></form>${S.google?`<div class="auth-separator">o también</div><button type="button" class="google-btn auth-google" id="startGoogle"><img src="${PREVIEW?window.RS_PREVIEW_GOOGLE:'/assets/google-g.svg'}" width="25" height="25" alt=""> <span>Continuar con Google</span></button>`:''}<div class="auth-guest-entry"><button class="btn btn-outline btn-wide" data-href="/inicio">Explorar tienda sin registrarme ${icon('arrow')}</button><p>Puedes explorar desde cualquier país. Las formas de pago actuales son para Cuba; nuevos métodos internacionales estarán disponibles cuando se habiliten.</p></div></div></section>`}

function profilePage(onboarding=false){if(!S.user)return authWelcome();const p=S.profile;return `<section class="card profile-card">${pagehead('PERFIL',p?'Tu cuenta Refills Shop':'Termina tu registro',p?'Estos datos se guardan en la base de datos.':'Último paso: escribe tu nombre y teléfono de contacto.')}<form id="profileForm" class="fields"><div class="field"><label>Nombre completo</label><input name="fullName" required minlength="2" maxlength="90" autocomplete="name" value="${esc(p?.fullName||'')}" placeholder="Nombre del titular"></div><div class="field"><label>Teléfono de contacto (con prefijo, p. ej. +5351234567)</label><input name="phone" required type="tel" inputmode="tel" minlength="8" maxlength="19" ${S.user?.user_metadata?.signup_source==='phone_password'?'readonly title="El número de acceso se cambia por soporte"':''} value="${esc(p?.phone||'')}" placeholder="+5351234567"></div><button class="btn btn-primary btn-wide" type="submit">Guardar y continuar →</button></form>${p?`<button class="btn btn-ghost btn-wide mt2" id="logout">Cerrar sesión</button>`:''}</section>`}
function account(){return S.user?profilePage():authWelcome()}
function statusName(s){return ({pending:'Pendiente',completed:'Completado',rejected:'Rechazado',uploading:'En preparación'})[s]||s}
function orderCard(o,admin=false){const status=esc(o.status);return `<article class="card order-card"><div class="order-top"><div><div class="order-code">PEDIDO ${esc(o.code)}</div><h3>${esc(o.game)} · ${esc(o.offer)}</h3></div><span class="state-pill ${status}">${esc(statusName(o.status))}</span></div><div class="order-details"><span>Pago: <strong>${esc(paymentName(o.method))}</strong></span><span>Importe: <strong>${money(o.amount)} ${esc(o.currency)}</strong></span><span>ID: <strong>${esc(o.playerId)}</strong></span></div><div class="timeline" aria-hidden="true"><span class="active"></span><span class="${o.status!=='pending'?'active':''}"></span><span class="${o.status==='completed'?'active':''}"></span></div><div class="order-actions"><small class="muted">${new Date(o.created).toLocaleString('es-ES')}</small><button class="btn btn-outline btn-sm" data-detail="${esc(o.code)}" ${admin?'data-admin="1"':''}>Ver detalles →</button></div></article>`}
function orders(){if(!S.user&&!PREVIEW)return `${pagehead('MIS PEDIDOS','Inicia sesión para ver tus compras')}<button class="btn btn-primary" data-href="/cuenta">Continuar</button>`;let list=S.orders.filter(o=>(S.filter==='all'||o.status===S.filter)&&(!S.search||o.code.toLowerCase().includes(S.search.toLowerCase())||(o.game+' '+o.offer).toLowerCase().includes(S.search.toLowerCase())));return `${pagehead('SEGUIMIENTO','Mis pedidos','Consulta el estado, importe y comprobación de cada compra.') }<div class="order-filters">${[['all','Todos'],['pending','Pendientes'],['completed','Completados'],['rejected','Rechazados']].map(([k,v])=>`<button class="chip ${S.filter===k?'active':''}" data-filter="${k}">${v}</button>`).join('')}</div><label class="search-field mb"><span>${icon('search')}</span><input id="orderSearch" value="${esc(S.search)}" placeholder="Buscar por código o juego"></label>${list.length?`<div class="order-list">${list.map(x=>orderCard(x)).join('')}</div>`:`<div class="card empty"><h3>No hay pedidos en esta sección</h3><p>Los pedidos enviados desde tu cuenta aparecerán aquí automáticamente.</p><button class="btn btn-primary" data-href="/catalogo">Buscar juegos →</button></div>`}`}
function reseller(){const active=S.member;const c=S.store.config;const samples=S.store.offers.slice(0,6);return `${pagehead('REVENDEDORES','Tu espacio de recargas','Mira cuánto te cuesta cada oferta antes de solicitar el plan.') }<div class="reseller-top"><section class="card pad"><div class="caps">${active?'WALLET DE REVENDEDOR':'SALDO USDT'}</div><div class="wallet-display">${S.wallet===null?'—':usdt(S.wallet)} <small>USDT</small></div><p class="muted">${active?'Saldo asociado a tu cuenta. Solo el servidor puede modificarlo.':'El saldo se mostrará al activar tu cuenta revendedora.'}</p>${active?`<span class="state-pill completed">Plan activo hasta ${new Date(S.expiry).toLocaleDateString('es-ES')}</span>`:''}</section><section class="card pad"><div class="caps">PLAN REVENDEDOR</div><h2 class="section-title">Acceso a precios especiales</h2><p class="muted">Consulta precios finales en USDT. Solo ves los importes finales de cada recarga, sin información interna del proveedor.</p><div class="wallet-display">${c.planPrice===null?'Por definir':usdt(c.planPrice)+' USDT'}</div><p class="small muted">Vigencia: ${Number(c.planDays||30)} días</p>${active?`<button class="btn btn-ghost btn-wide" data-href="/catalogo">Ver catálogo</button>`:`<button class="btn btn-primary btn-wide" id="requestPlan" ${c.planPrice===null?'disabled':''}>Solicitar plan →</button>`}<p class="tiny muted">Solicitud sujeta a verificación manual del pago. No se activa automáticamente.</p></section></div><section class="mt"><div class="section-head"><div><div class="caps">VISTA PREVIA</div><h2>Precios para revendedores</h2></div></div>${samples.length?`<div class="price-preview">${samples.map(o=>{const g=game(o.gameId);return `<article class="card reseller-price"><img class="mini-cover" src="${esc(coverSrc(g||{id:'fallback',name:'Juego'}))}" data-cover-id="${esc(g?.id||'fallback')}" alt="${esc(g?.name||'Juego')}"><h3>${esc(g?.name||'Juego')}<br>${esc(o.name)}</h3><small>Precio final</small><strong>${usdt(o.resellerUsdt)} <small>USDT</small></strong></article>`}).join('')}</div>`:`<div class="card empty">Las ofertas se publicarán desde el ADM.</div>`}</section>`}
function manualContactUrl(phone,channel,name){
 const digits=String(phone||'').replace(/[^0-9]/g,'');
 if(digits.length<8||digits.length>15)return null;
 const text=`Hola ${String(name||'').trim()||'cliente'}, te contactamos desde Refills Shop porque se registró una cuenta con este número. ¿Fuiste tú? No envíes contraseñas ni códigos por este chat.`;
 return channel==='whatsapp'?'https://wa.me/'+digits+'?text='+encodeURIComponent(text):'sms:+'+digits+'?body='+encodeURIComponent(text);
}
function adminCustomerCard(c){
 const phone=String(c.phone||''),status=c.reviewStatus||'pending';
 const label=({pending:'Nuevo · Sin contactar',contacted:'Contacto gestionado',confirmed:'Registro confirmado manualmente'})[status]||'Sin revisar';
 const valid=/^\+[1-9][0-9]{7,14}$/.test(phone);
 return `<article class="admin-client"><div class="admin-client-icon">${icon('shield')}</div><div class="admin-client-main"><strong>${esc(c.name||'Sin completar perfil')}</strong><small>${esc(phone||c.email||'Sin teléfono')} · ${c.createdAt?new Date(c.createdAt).toLocaleString('es-ES'):''}</small><span class="state-pill ${status==='confirmed'?'completed':'pending'}">${esc(label)}</span><small>${c.orders} pedidos · ${usdt(c.balanceUsdt)} USDT</small><small>Teléfono ${c.phoneVerified?'verificado por proveedor':'sin verificación técnica'}</small></div><div class="admin-contact-buttons"><button class="btn btn-outline btn-sm" data-contact="whatsapp" data-customer-id="${esc(c.id)}" ${valid?'':'disabled'}>WhatsApp</button><button class="btn btn-outline btn-sm" data-contact="sms" data-customer-id="${esc(c.id)}" ${valid?'':'disabled'}>SMS</button>${status==='pending'?`<button class="btn btn-ghost btn-sm" data-review="contacted" data-customer-id="${esc(c.id)}">Marcar contactado</button>`:''}${status!=='confirmed'?`<button class="btn btn-primary btn-sm" data-review="confirmed" data-customer-id="${esc(c.id)}">Confirmó que se registró</button>`:''}<button class="btn btn-ghost btn-sm" data-edit-customer="${esc(c.id)}">Editar</button></div></article>`
}
function adminTabs(){const tabs=[['/admin','Resumen'],['/admin/orders','Pedidos'],['/admin/offers','Juegos y ofertas'],['/admin/settings','Tasas y pagos'],['/admin/resellers','Revendedores'],['/admin/customers','Clientes'],['/admin/fulfillment','Recargas reales'],['/admin/integrations','Conexiones']];return `<div class="admin-tabs">${tabs.map(([url,t])=>`<button class="chip ${S.route===url?'active':''}" data-href="${url}">${t}</button>`).join('')}<button class="chip" id="logoutAdmin">Salir</button></div>`}
function adminLogin(){return `${pagehead('ACCESO RESERVADO','Administración','Ruta privada: /admin')}<section class="card profile-card"><div class="caps">PANEL ADM</div><h2>Acceso del administrador</h2><p class="muted">${PREVIEW?'Acceso de revisión local. Para administrar la tienda necesitas el servidor conectado.':S.adminConfigured===false?'El servidor no cargó ADMIN_PASSWORD. Comprueba el archivo .env y reinicia el servidor.':'La contraseña se valida exclusivamente en el servidor.'}</p><form id="adminLoginForm" class="fields"><div class="field"><label>Contraseña</label><input type="password" name="password" autocomplete="off" required placeholder="Contraseña del servidor"></div><div id="adminError" class="notice error hide">Contraseña incorrecta o servidor sin configurar.</div><button type="submit" class="btn btn-primary btn-wide">Entrar al ADM →</button></form>${PREVIEW?'<button type="button" class="btn btn-outline btn-wide mt2" id="previewAdmin">Ver panel ADM de ejemplo (sin datos reales)</button>':''}</section>`}
function admin(){if(!S.admin)return adminLogin();let body='';if(S.route==='/admin')body=`<section class="card pad mb"><div class="section-head"><div><div class="caps">NUEVOS REGISTROS</div><h2>Revisión de clientes</h2></div><button class="btn btn-outline" data-href="/admin/customers">Abrir bandeja →</button></div><p class="muted">Nuevos pendientes de contacto: <strong>${S.adminCustomers.filter(c=>c.reviewStatus==='pending').length}</strong>. Actualiza para recibir nuevos avisos.</p><button class="btn btn-ghost btn-sm" id="refreshCustomers">Actualizar avisos</button></section><div class="admin-stats"><div class="card stat"><small>Juegos visibles</small><strong>${S.store.games.length}</strong></div><div class="card stat"><small>Ofertas activas</small><strong>${S.store.offers.length}</strong></div><div class="card stat"><small>Pedidos cargados</small><strong>${S.adminOrders.length}</strong></div></div><div class="admin-grid"><section class="card pad"><h2>Catálogo del proveedor</h2><p class="muted">Consulta RecargasAmérica y publica solo los productos que quieras vender.</p><button class="btn btn-primary" data-href="/admin/offers">Crear oferta API →</button></section><section class="card pad"><h2>Gestión de pedidos</h2><p class="muted">Busca un código, revisa el comprobante y completa o rechaza manualmente.</p><button class="btn btn-outline" data-href="/admin/orders">Ver pedidos →</button></section></div>`;
if(S.route==='/admin/orders')body=`<section class="card pad"><div class="section-head"><h2>Solicitudes de compra</h2><button class="btn btn-outline btn-sm" id="reloadAdminOrders">Actualizar</button></div><form id="adminOrderSearchForm" class="flex mb"><div class="field" style="flex:1;min-width:180px"><input name="q" placeholder="Buscar código RS-..." value="${esc(S.admSearch)}"></div><button class="btn btn-primary" type="submit">Buscar</button></form>${S.adminOrders.length?`<div class="order-list">${S.adminOrders.map(o=>orderCard(o,true)).join('')}</div>`:`<div class="notice">Todavía no hay solicitudes que coincidan.</div>`}</section>`;
if(S.route==='/admin/offers')body=`<div class="admin-grid"><section class="card pad"><h2>Vincular oferta del proveedor</h2><p class="muted small">Central One o RecargasAmérica: los costos se leen del proveedor, sin compartir tu clave con el navegador. La ganancia SM es privada.</p><div class="field mb"><label for="providerPicker">Proveedor del catálogo</label><select id="providerPicker"><option value="centralone" ${S.selectedProvider==='centralone'?'selected':''}>Central One · catálogo nuevo</option><option value="recargasamerica" ${S.selectedProvider==='recargasamerica'?'selected':''}>RecargasAmérica · alternativo</option></select></div><div class="btn-row mb"><button class="btn btn-outline" id="loadProvider">${icon('search')} Leer productos</button><button class="btn btn-ghost" id="syncProvider">${icon('clock')} Actualizar costos</button></div>${S.selectedProvider==='centralone'&&S.apiProducts.length?`<form id="adminFamilyForm" class="admin-form import-panel mb"><div class="caps">PUBLICAR UNA FAMILIA COMPLETA</div><p class="muted small">Importa todas las denominaciones disponibles de un juego con una sola acción (hasta 40 productos).</p><div class="field"><label>Juego de tu web</label><select name="gameId" required>${S.store.games.map(g=>`<option value="${esc(g.id)}">${esc(g.name)}</option>`).join('')}</select></div><div class="field"><label>Familia del proveedor</label><select name="familyId" required>${[...new Map(S.apiProducts.filter(x=>x.familyId).map(x=>[x.familyId,x])).values()].slice(0,500).map(x=>`<option value="${esc(x.familyId)}">${esc(x.family||x.name)} · ${esc(x.region||'GLOBAL')}</option>`).join('')}</select></div><div class="field"><label>Ganancia SM por cada oferta</label><input type="number" name="gainSm" min="0" step="0.01" value="0" required></div><button class="btn btn-primary btn-wide" type="submit">Importar familia del catálogo →</button></form>`:''}<form id="adminOfferForm" class="admin-form"><div class="field"><label>Juego</label><select name="gameId" required>${S.store.games.map(g=>`<option value="${esc(g.id)}">${esc(g.name)}</option>`).join('')}</select></div><div class="field"><label>Producto del proveedor</label><select name="productId" required>${S.apiProducts.length?S.apiProducts.map(p=>`<option value="${esc(p.id)}">${esc(p.name)} · ${money(p.price)} USDT${p.region?' · '+esc(p.region):''}</option>`).join(''):'<option value="">Pulsa Leer productos</option>'}</select></div><div class="field"><label>Ganancia SM por oferta</label><input name="gainSm" type="number" min="0" step="0.01" value="0" required></div><button class="btn btn-primary btn-wide" type="submit">Publicar oferta vinculada →</button></form></section><section class="card pad"><h2>Crear o editar juego</h2><form id="adminGameForm" class="admin-form"><div class="field"><label>ID del juego (por ejemplo free-fire)</label><input name="id" placeholder="free-fire" pattern="[a-z0-9-]{2,60}" required></div><div class="field"><label>Nombre</label><input name="name" maxlength="90" required></div><div class="field"><label>Categoría</label><input name="category" placeholder="Battle Royale" required></div><div class="field"><label>Imagen HTTPS</label><input name="imageUrl" type="url" placeholder="https://..."></div><label class="checkbox-line"><input name="featured" type="checkbox"> Mostrar entre los tres juegos de inicio</label><button class="btn btn-outline btn-wide" type="submit">Guardar juego</button></form><h3 class="mt2">Juegos existentes</h3><div class="admin-entity-list">${S.store.games.map(g=>`<article class="admin-entity"><img src="${esc(coverSrc(g))}" alt=""><div><strong>${esc(g.name)}</strong><small>${esc(g.tag||'Juegos')} · ${offers(g.id).length} ofertas</small></div><button class="btn btn-sm btn-outline" data-edit-game="${esc(g.id)}">Editar</button><button class="btn btn-sm btn-red" data-delete-game="${esc(g.id)}">Eliminar</button></article>`).join('')}</div></section></div><section class="card pad mt"><div class="section-head"><div><h2>Ofertas publicadas</h2><p class="muted small">Edita ganancia, activa/desactiva o retira ofertas. Las inactivas también se consultan desde la base de datos.</p></div></div><div class="admin-entity-list">${(S.adminAllOffers.length?S.adminAllOffers.map(raw=>({id:raw.id,gameId:raw.game_id,name:raw.name,resellerUsdt:Number(raw.provider_price_usdt)*1.03,usdt:Number(raw.provider_price_usdt),inStock:raw.provider_in_stock,active:raw.active})):S.store.offers).map(o=>{const g=game(o.gameId);return `<article class="admin-entity"><div class="admin-entity-thumb">${icon('bag')}</div><div><strong>${esc(g?.name||'Juego')} · ${esc(o.name)}</strong><small>${usdt(o.resellerUsdt||o.usdt)} USDT revendedor · ${o.inStock===false?'Agotado':o.active===false?'Desactivada':'Disponible'}</small></div><button class="btn btn-sm btn-outline" data-edit-offer="${esc(o.id)}">Editar</button><button class="btn btn-sm btn-red" data-delete-offer="${esc(o.id)}">Eliminar</button></article>`}).join('')}</div></section>`;
if(S.route==='/admin/settings'){const c=S.store.config;body=`<section class="card profile-card"><h2>Precios, tasas y pagos</h2><form id="adminSettingsForm" class="fields"><div class="twofields"><div class="field"><label>SM por 1 USDT</label><input name="buySmPerUsdt" type="number" step="0.01" min="1" value="${esc(c.buySmPerUsdt)}" required></div><div class="field"><label>CUP por 1 SM</label><input name="cupPerSm" type="number" step="0.01" min="0.01" value="${esc(c.cupPerSm)}" required></div></div><div class="field"><label>Recargo al pagar con tarjeta (%)</label><input name="cardFee" type="number" min="0" max="100" step="0.01" value="${esc(c.cardFee)}" required></div><div class="twofields"><div class="field"><label>Número saldo móvil</label><input name="mobilePhone" maxlength="8" value="${esc(c.mobilePhone||'')}" required></div><div class="field"><label>Monedero MiTransfer</label><input name="walletPhone" maxlength="8" value="${esc(c.walletPhone||'')}"></div></div><div class="field"><label>Tarjeta CUP</label><input name="cardNumber" value="${esc(c.cardNumber||'')}" required></div><div class="field"><label>Confirmación por teléfono</label><input name="confirmPhone" maxlength="8" value="${esc(c.confirmPhone||'')}" required></div><div class="twofields"><div class="field"><label>Precio del plan revendedor USDT</label><input name="planPrice" type="number" min="0.01" step="0.01" value="${c.planPrice??''}" placeholder="Por definir"></div><div class="field"><label>Días del plan</label><input name="planDays" type="number" min="1" max="365" value="${esc(c.planDays)}"></div></div><button class="btn btn-primary btn-wide" type="submit">Guardar en Supabase ahora →</button></form></section>`}
if(S.route==='/admin/resellers')body=`<section class="card pad"><div class="section-head"><h2>Solicitudes de plan revendedor</h2><button class="btn btn-outline" id="refreshPlans">Actualizar</button></div>${S.planRequests.length?S.planRequests.map(r=>`<div class="order-card" style="border-bottom:1px solid #315170"><strong>Solicitud #${r.id}</strong><p class="muted tiny">Usuario: ${esc(r.user_id)}</p><p>Plan: ${usdt(r.plan_price_usdt)} USDT · ${r.plan_days} días</p><span class="state-pill ${r.status}">${esc(statusName(r.status))}</span>${r.status==='pending'?`<div class="btn-row mt2"><button class="btn btn-primary" data-approve-plan="${r.id}">Aprobar tras comprobar pago</button><button class="btn btn-red" data-reject-plan="${r.id}">Rechazar</button></div>`:''}</div>`).join(''):'<div class="notice">No hay solicitudes por el momento.</div>'}</section>`;

if(S.route==='/admin/customers')body=`<section class="card pad"><div class="section-head"><div><h2>Registros y clientes</h2><p class="muted small">Un cliente puede registrarse sin código. Tu confirmación es manual y no equivale a verificar la propiedad del número.</p></div><button class="btn btn-outline btn-sm" id="refreshCustomers">Actualizar registros</button></div><div class="admin-stats"><div class="card stat"><small>Clientes registrados</small><strong>${S.adminCustomers.length}</strong></div><div class="card stat"><small>Nuevos sin contactar</small><strong>${S.adminCustomers.filter(c=>c.reviewStatus==='pending').length}</strong></div><div class="card stat"><small>Confirmados por ADM</small><strong>${S.adminCustomers.filter(c=>c.reviewStatus==='confirmed').length}</strong></div></div><div class="notice warn mb">WhatsApp y SMS se abren en tu dispositivo con un mensaje preparado. TÚ decides si enviarlo. El sistema no marca el mensaje como enviado ni el teléfono como verificado automáticamente.</div>${S.adminCustomers.length?`<div class="admin-client-list">${S.adminCustomers.slice().sort((a,b)=>Number(a.reviewStatus!=='pending')-Number(b.reviewStatus!=='pending')||Date.parse(b.createdAt||0)-Date.parse(a.createdAt||0)).map(c=>adminCustomerCard(c)).join('')}</div>`:'<div class="notice">Todavía no hay clientes. Cada registro nuevo aparecerá aquí.</div>'}</section>`;
if(S.route==='/admin/fulfillment')body=`<section class="card pad"><div class="section-head"><div><h2>Recargas Central One</h2><p class="muted">Compra únicamente después de comprobar el pago recibido. Cada pedido tiene una clave única para evitar duplicados.</p></div><button id="refreshFulfillments" class="btn btn-outline btn-sm">Actualizar</button></div><div class="notice warn mb">Las recargas reales están bloqueadas hasta configurar CENTRALONE_API_KEY, SUPABASE_SECRET_KEY y CENTRALONE_ORDER_ENABLED=true. Una compra al proveedor consume tu saldo.</div>${S.adminOrders.filter(o=>o.status==='pending').length?`<div class="admin-client-list">${S.adminOrders.filter(o=>o.status==='pending').map(o=>{const f=S.adminFulfillments.find(f=>f.order_id===o.id);return `<article class="admin-client"><div class="admin-client-icon">${icon('bag')}</div><div class="admin-client-main"><strong>${esc(o.code)} · ${esc(o.game)}</strong><small>${esc(o.offer)} · ${esc(o.playerId)} · ${money(o.amount)} ${esc(o.currency)}</small><small>${f?'Proveedor: '+esc(f.status)+' · '+esc(f.provider_status||'sin confirmar'):'Pendiente de comprobación de pago'}</small></div>${f?`<button class="btn btn-outline btn-sm" data-reconcile="${esc(o.id)}" ${!f.provider_order_id?'disabled':''}>Consultar estado</button>`:`<button class="btn btn-primary btn-sm" data-fulfill="${esc(o.code)}">Pago verificado → Recargar</button>`}</article>`}).join('')}</div>`:'<div class="notice">No hay pedidos pendientes de recarga.</div>'}</section>`;
if(S.route==='/admin/integrations')body=`<div class="admin-grid"><section class="card pad"><div class="caps">BASE DE DATOS</div><h2>Supabase</h2><p class="muted">Juegos, ofertas, perfiles y pedidos se guardan en tu proyecto nuevo. La clave privada solo pertenece al servidor.</p><span class="state-pill ${S.databaseConfigured?'completed':'pending'}">${S.databaseConfigured?'Servidor conectado':'Falta clave privada de servidor'}</span><p class="tiny muted">No se permite administrar saldos directamente desde el navegador.</p></section><section class="card pad"><div class="caps">PROVEEDOR PRINCIPAL</div><h2>Central One</h2><p class="muted">Lee su catálogo con permiso catalog:read; las compras usan orders:write con confirmación manual e idempotencia.</p><button class="btn btn-primary" data-href="/admin/offers">Importar ofertas →</button><p class="tiny muted">Si no se ha guardado CENTRALONE_API_KEY en el servidor, el catálogo real no puede cargarse.</p></section><section class="card pad"><div class="caps">AUTENTICACIÓN</div><h2>Inicio con Google</h2><p class="muted">OAuth requiere configurar Client ID, Client Secret y la URL de retorno en Supabase y Google Cloud.</p><span class="state-pill ${S.google?'completed':'pending'}">${S.google?'Habilitado en el servidor':'OAuth pendiente de activación'}</span><p class="tiny muted">URL de retorno: https://kcgjlnymhmxylrjchcvl.supabase.co/auth/v1/callback</p></section><section class="card pad"><div class="caps">ADMINISTRACIÓN</div><h2>Pedidos y seguridad</h2><p class="muted">Revisa comprobantes privados, ajusta tasas, aprueba planes y consulta la entrega en el proveedor.</p><button class="btn btn-outline" data-href="/admin/orders">Gestionar pedidos →</button></section></div>`;
return `${PREVIEW?'<div class="notice warn mb">ADM de revisión local · Para guardar los cambios abre el proyecto mediante el servidor.</div>':S.databaseConfigured===false?'<div class="notice warn mb">Acceso correcto. Para guardar pedidos y cambios del ADM falta configurar SUPABASE_SECRET_KEY en el servidor.</div>':''}${S.storeError&&!PREVIEW?'<div class="notice warn mb">'+esc(S.storeError)+'</div>':''}${pagehead('ADMINISTRACIÓN','Centro de control','Solo se accede directamente por /admin. Ninguna función publica las claves privadas.')} ${adminTabs()} ${body}`}
function routeLabel(){const path=PREVIEW?(new URLSearchParams(location.search).get('ruta')||S.route):location.pathname;const names={'/inicio':'Inicio','/catalogo':'Catálogo','/pedidos':'Mis pedidos','/revendedores':'Revendedores','/cuenta':'Mi cuenta','/compra/datos':'Datos de compra','/compra/pago':'Pago','/compra/revision':'Revisión','/compra/listo':'Confirmación'};return names[path]||(/\/juegos\//.test(path)?'Ofertas del juego':path.replace(/^\//,'').replace(/-/g,' '))} 
function render(){if(!S.ready)return;const isAdmin=S.route.startsWith('/admin');const isLoginGate=!S.user&&((S.route==='/'&&!S.guestEntered)||S.route==='/account');document.body.classList.toggle('auth-guest',isLoginGate);document.body.classList.toggle('admin-view',isAdmin);$('topnav').innerHTML=(isAdmin||isLoginGate)?'':[['/inicio','Inicio','game'],['/catalogo','Juegos','search'],['/pedidos','Mis pedidos','bag'],['/revendedores','Revendedor','wallet'],['/cuenta','Cuenta','shield']].map(([p,t,i])=>`<button class="navlink ${S.route===canonical(p)?'active':''}" data-href="${p}">${icon(i)} ${t}</button>`).join('');$('bottomnav').style.display=(isAdmin||isLoginGate)?'none':'';$('bottomnav').innerHTML=(isAdmin||isLoginGate)?'':[['/inicio','Juegos','game'],['/catalogo','Explorar','search'],['/pedidos','Pedidos','bag'],['/revendedores','Revendedor','wallet'],['/cuenta','Cuenta','shield']].map(([p,t,i])=>`<a href="${p}" data-link class="${S.route===canonical(p)?'active':''}"><span class="ico">${icon(i)}</span>${t}</a>`).join('');$('balanceValue').textContent=usdt(S.wallet===null?0:S.wallet);let body='';if(isAdmin)body=admin();else if(S.user&&!S.profile&&S.route!=='/account')body=profilePage(true);else if(S.route==='/')body=(S.user||S.guestEntered)?home():authWelcome();else if(S.route==='/account')body=account();else if(S.route==='/catalog')body=catalog();else if(S.route.startsWith('/games/'))body=gamePage(decodeURIComponent(S.route.split('/')[2]||''));else if(S.route==='/checkout')body=checkout();else if(S.route==='/orders')body=orders();else if(S.route==='/reseller')body=reseller();else body=home();$('app').innerHTML=(!isLoginGate&&S.route!=='/'&&!isAdmin?'<div class="route-trail">'+icon('arrow')+' <span>REFILLS SHOP</span><span>/</span><strong>'+esc(routeLabel())+'</strong></div>':'')+body;}
async function api(url,{method='GET',body,auth=false}={}){const headers={'Accept':'application/json'};if(body!==undefined)headers['Content-Type']='application/json';if(auth){const result=await S.client?.auth.getSession();const token=result?.data?.session?.access_token;if(!token)throw Error('Tu sesión ha expirado. Inicia sesión otra vez.');headers.Authorization='Bearer '+token}let response;try{response=await fetch(url,{method,headers,body:body===undefined?undefined:JSON.stringify(body),credentials:'same-origin',cache:'no-store'})}catch{throw Error('No hay conexión con el servidor. Reintenta.')}let parsed;try{parsed=await response.json()}catch{throw Error('El servidor respondió con un formato incorrecto')}if(!response.ok)throw Error(parsed.error||'Operación no disponible');return parsed}
async function loadProfile(){if(PREVIEW||!S.user){S.profile=null;S.member=false;S.wallet=null;return}const data=await api('/api/profile',{auth:true});S.profile=data.profile;S.member=data.resellerActive;S.wallet=data.walletUsdt;S.expiry=data.expiresAt}
async function loadOrders(){if(PREVIEW){S.orders=[];render();return}if(!S.user)return;try{const data=await api('/api/orders',{auth:true});S.orders=data.orders||[];render()}catch(e){notify(e.message)}}
async function loadAdminOrders(){if(PREVIEW)return;try{S.adminOrders=(await api('/api/admin/orders'+(S.admSearch?'?q='+encodeURIComponent(S.admSearch):''))).orders||[];render()}catch(e){notify(e.message)}}
async function loadPlanRequests(){if(PREVIEW)return;try{S.planRequests=(await api('/api/admin/plan-requests')).requests||[];render()}catch(e){notify(e.message)}}
async function loadCustomers(){
 if(PREVIEW||!S.admin)return;
 try{
  const incoming=(await api('/api/admin/customers')).clients||[];
  const prev=new Set(S.adminCustomers.map(c=>c.id));
  const newlyPending=incoming.filter(c=>c.reviewStatus==='pending'&&!prev.has(c.id));
  if(S.customerScanInitialized&&newlyPending.length){notify(newlyPending.length===1?'Hay un registro nuevo pendiente de revisión.':`Hay ${newlyPending.length} registros nuevos pendientes.`)}
  S.adminCustomers=incoming;S.customerScanInitialized=true;render();
 }catch(e){notify(e.message)}
}
// Only while the private ADM is open: refresh the inbox periodically. No external messaging is automated.
setInterval(()=>{if(!PREVIEW&&S.admin&&S.route.startsWith('/admin'))loadCustomers()},45000);
async function loadAdminAllOffers(){if(PREVIEW)return;try{S.adminAllOffers=(await api('/api/admin/offers')).offers||[];render()}catch(e){notify(e.message)}}
async function loadFulfillments(){if(PREVIEW)return;try{S.adminFulfillments=(await api('/api/admin/fulfillments')).fulfillments||[];render()}catch(e){notify(e.message)}}
async function loadAdminOverview(){if(PREVIEW)return;try{S.adminOverview=await api('/api/admin/overview');render()}catch(e){notify(e.message)}}
async function loadProvider(){try{if(PREVIEW)throw Error('El catálogo proveedor requiere servidor y clave API privada.');const data=await api('/api/catalog?provider='+encodeURIComponent(S.selectedProvider));S.apiProducts=data.products||[];notify('Productos disponibles: '+S.apiProducts.length);render()}catch(e){notify(e.message)}}
async function bootstrap(){const splash=$('splash'),msg=$('splashMessage');$('splashRetry').classList.add('hide');splash.classList.remove('hide');msg.textContent='Conectando con Refills Shop y sincronizando cambios…';try{
if(PREVIEW){hydratePath(new URLSearchParams(location.search).get('ruta')||'/');S.store=LOCAL_VIEW_STORE;S.google=false;S.ready=true;S.profile=null;S.wallet=null;}
else{hydratePath(location.pathname);const data=await api('/api/bootstrap');S.store=data.storefront||{live:false,games:[],offers:[],config:{buySmPerUsdt:350,cupPerSm:3,cardFee:5,mobilePhone:'50237996',walletPhone:'',cardNumber:'9204-1299-7870-3553',confirmPhone:'50237996',planPrice:null,planDays:30}};S.storeError=data.storefrontError||null;S.google=!!data.googleLoginEnabled;S.adminConfigured=!!data.adminConfigured;S.databaseConfigured=!!data.databaseConfigured;
 if(data.supabaseUrl&&data.publishableKey&&window.supabase?.createClient){S.client=window.supabase.createClient(data.supabaseUrl,data.publishableKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});const result=await S.client.auth.getUser();S.user=result.data?.user||null;if(S.user)await loadProfile();S.client.auth.onAuthStateChange((evt,session)=>{const id=session?.user?.id||null;if(id!==S.user?.id){S.user=session?.user||null;setTimeout(async()=>{try{await loadProfile();render()}catch(e){notify(e.message)}},0)}})}else if(!S.route.startsWith('/admin'))throw Error('No se pudo cargar el acceso de usuarios. Comprueba la conexión y la configuración.');
 if(S.route.startsWith('/admin')){try{S.admin=(await api('/api/admin/session')).admin}catch{S.admin=false}}}
S.ready=true;splash.classList.add('hide');render();if(S.route==='/orders')loadOrders();if(S.route==='/admin/orders')loadAdminOrders();if(S.route==='/admin/resellers')loadPlanRequests();if(S.route==='/admin/customers'||S.route==='/admin')loadCustomers();if(S.route==='/admin/fulfillment'){loadAdminOrders();loadFulfillments()}if(S.route==='/admin/offers')loadAdminAllOffers();if(S.route==='/admin/integrations')loadAdminOverview();}
catch(e){S.ready=false;msg.textContent=e.message||'Fallo al sincronizar. La tienda no mostrará datos antiguos.';$('splashRetry').classList.remove('hide');}}
async function startGoogle(){if(!S.google||!S.client){notify('Google todavía no está habilitado para esta tienda.');return}try{const {error}=await S.client.auth.signInWithOAuth({provider:'google',options:{redirectTo:location.origin+'/inicio',queryParams:{prompt:'select_account'}}});if(error)throw error}catch(e){notify('No se pudo abrir Google: '+e.message)}}
async function saveProfile(f){try{if(PREVIEW){notify('Vista previa: los datos no se envían a ningún servidor.');return}const b={fullName:f.elements.fullName.value.trim(),phone:f.elements.phone.value.trim()};const result=await api('/api/profile',{method:'PUT',auth:true,body:b});S.profile=result.profile;notify('Perfil guardado correctamente.');route('/inicio')}catch(e){notify(e.message)}}
async function submitOrder(){if(!$('confirmOrder')?.checked){notify('Confirma que revisaste los datos.');return}if(!S.proof){notify('Falta adjuntar el comprobante.');return}if(PREVIEW){notify('La vista previa no acepta pedidos reales.');return}const button=$('sendOrder');button.disabled=true;button.textContent='Enviando comprobante…';try{if(!S.requestId)S.requestId=crypto.randomUUID();const result=await api('/api/orders',{method:'POST',auth:true,body:{gameId:S.gameId,offerId:S.offerId,playerId:S.playerId,zoneId:S.zoneId,targetPayload:S.targetPayload,method:S.payment,sourcePhone:S.payment==='mobile'?S.sourcePhone:'',receipt:S.proof,clientRequestId:S.requestId}});S.lastOrder=result.order;S.step=4;S.proof=null;route(checkoutPaths[4]);notify('Pedido enviado a revisión.')}catch(e){button.disabled=false;button.textContent='Enviar solicitud →';notify(e.message)}}
function clearCheckout(){S.step=1;S.playerId='';S.zoneId='';S.payment='mobile';S.sourcePhone='';S.targetPayload={};S.proof=null;S.proofName='';S.requestId=null;S.lastOrder=null}
async function readReceipt(file){if(!file||!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Solo se permiten imágenes JPG, PNG o WEBP.');if(file.size>3*1024*1024||file.size<200)throw Error('La captura debe tener entre 200 bytes y 3 MB.');return new Promise((ok,fail)=>{const r=new FileReader();r.onerror=()=>fail(Error('No se pudo leer la captura.'));r.onload=()=>ok(r.result);r.readAsDataURL(file)})}
function showDetail(code,admin){const list=admin?S.adminOrders:S.orders,o=list.find(x=>x.code===code);if(!o)return;const receipt=admin&&o.receiptAvailable?`<img class="admin-image" src="/api/admin/receipt?code=${encodeURIComponent(code)}" alt="Comprobante del pedido" loading="lazy">`:o.receiptAvailable?'El comprobante está almacenado de forma privada.':'Sin comprobante';$('modal').innerHTML=`<div class="card modal-card" role="dialog" aria-modal="true"><div class="modal-head"><h2>Pedido ${esc(o.code)}</h2><button class="btn btn-ghost btn-sm" id="closeModal">Cerrar</button></div><span class="state-pill ${esc(o.status)}">${esc(statusName(o.status))}</span><div class="mt2"><div class="sum-row"><span>Juego</span><strong>${esc(o.game)}</strong></div><div class="sum-row"><span>Oferta</span><strong>${esc(o.offer)}</strong></div><div class="sum-row"><span>ID</span><strong>${esc(o.playerId)}</strong></div>${Object.entries(o.targetPayload||{}).filter(([k,v])=>k!=='player_id'&&String(v).length<150).map(([k,v])=>`<div class="sum-row"><span>${esc(k.replace(/_/g,' '))}</span><strong>${esc(v)}</strong></div>`).join('')}<div class="sum-row"><span>Método</span><strong>${esc(paymentName(o.method))}</strong></div><div class="sum-row"><span>Importe</span><strong>${money(o.amount)} ${esc(o.currency)}</strong></div>${o.note?`<div class="notice">${esc(o.note)}</div>`:''}<div class="mt2">${receipt}</div>${admin&&o.status==='pending'?`<div class="btn-row mt2"><button class="btn btn-primary" data-admin-status="completed" data-code="${esc(o.code)}">Marcar completado</button><button class="btn btn-red" data-admin-status="rejected" data-code="${esc(o.code)}">Rechazar</button></div>`:''}</div></div>`}
async function changeOrderStatus(code,status){if(!confirm(status==='completed'?'¿Confirmas que realizaste la recarga y verificaste su resultado?':'¿Rechazar este pedido?'))return;try{if(PREVIEW)throw Error('El ADM real no se usa desde la vista previa.');await api('/api/admin/order-status',{method:'POST',body:{code,status,note:''}});$('modal').innerHTML='';await loadAdminOrders();notify('Estado actualizado en la base de datos.')}catch(e){notify(e.message)}}
async function adminAction(action,body){if(PREVIEW)throw Error('Sin backend en vista previa.');return api('/api/admin/'+action,{method:'POST',body})}
async function doPlanRequest(){if(!S.user){route('/cuenta');notify('Inicia sesión antes de solicitar un plan.');return}if(!S.profile){route('/cuenta');return}if(!confirm('¿Enviar solicitud del plan por '+usdt(S.store.config.planPrice)+' USDT? No se realizará ningún cargo automático.'))return;try{const d=await api('/api/reseller/request',{method:'POST',body:{},auth:true});notify(d.message||'Solicitud registrada, pendiente de aprobación.')}catch(e){notify(e.message)}}
async function planStatus(id,approve){if(!confirm(approve?'¿Verificaste de verdad el pago del plan antes de activarlo?':'¿Rechazar esta solicitud?'))return;try{await adminAction(approve?'approve-plan':'plan-reject',{requestId:Number(id),...(approve?{confirmedPayment:true}:{})});await loadPlanRequests();notify('Solicitud procesada.')}catch(e){notify(e.message)}}
async function processForms(f){const form=f.id;if(form==='playerForm'){const {o}=selection(),schema=targetSchema(o);if(schema.length){S.targetPayload={};for(const field of schema){const value=String(f.elements['target_'+field.key]?.value||'').trim();if(!value||value.length>64)return notify('Completa '+(field.label||field.key));S.targetPayload[field.key]=value;}S.playerId=String(S.targetPayload.player_id||S.targetPayload.user_id||S.targetPayload.service_user_id||Object.values(S.targetPayload)[0]||'SIN-DATOS').slice(0,80);S.zoneId=String(S.targetPayload.zone_id||S.targetPayload.server||'').slice(0,30)}else{S.playerId=f.elements.playerId.value.trim();S.zoneId=f.elements.zoneId.value.trim();S.targetPayload={}}if(S.playerId.length<3)return notify('Revisa el ID de jugador.');S.step=2;route(checkoutPaths[2]);return}
if(form==='paymentForm'){S.payment=f.elements.payment.value;S.sourcePhone=S.payment==='mobile'?$('originPhone')?.value.trim()||'':'';if(S.payment==='mobile'&&!/^[0-9]{8}$/.test(S.sourcePhone))return notify('El teléfono de origen necesita ocho dígitos.');if(S.payment==='wallet'&&!S.store.config.walletPhone)return notify('MiTransfer todavía no está configurado.');const file=$('proofFile')?.files[0];if(!file&&!S.proof)return notify('Adjunta una captura del comprobante.');try{if(file){S.proof=await readReceipt(file);S.proofName=file.name;}S.step=3;route(checkoutPaths[3])}catch(e){notify(e.message)}return}
if(form==='profileForm')return saveProfile(f);
if(form==='phoneAuthForm'){
 if(PREVIEW){notify('Vista previa. Para registrarte necesitas el servidor conectado.');return}
 if(!S.client){notify('La autenticación no está configurada en el servidor.');return}
 const button=f.querySelector('[type="submit"]');if(button)button.disabled=true;
 try{
  const phone=internationalPhoneFromForm(f),password=f.elements.password.value;
  // International E.164 numbers are validated again on the server.
  if(S.phoneRegister){
   const fullName=f.elements.fullName.value.trim();
   if(password.length<10||!/[A-Za-zÁÉÍÓÚáéíóúÑñ]/.test(password)||!/[0-9]/.test(password))throw Error('La contraseña necesita 10 caracteres, letras y números.');
   await api('/api/auth/phone-register',{method:'POST',body:{fullName,phone,password,website:f.elements.website.value}});
  }
  const email=aliasForInternationalPhone(phone);
  const {data,error}=await S.client.auth.signInWithPassword({email,password});if(error)throw Error('Número o contraseña incorrectos.');
  S.user=data.user;await loadProfile();route('/inicio');notify(S.phoneRegister?'Cuenta creada. Tu número aún no está verificado.':'Bienvenido de nuevo.');
 }catch(e){notify(e.message||'No se pudo completar el acceso.');}
 finally{if(button)button.disabled=false;}
 return;
}
if(form==='adminLoginForm'){if(PREVIEW){notify('El ADM real requiere ejecutar el servidor Node con Supabase configurado. Esta vista es solo de exploración.');return}try{const d=await api('/api/admin/login',{method:'POST',body:{password:f.elements.password.value}});S.admin=!!d.ok;if(!S.admin)throw Error('Acceso no autorizado');route('/admin');loadAdminOrders();loadCustomers()}catch(e){$('adminError')?.classList.remove('hide');f.elements.password.value='';notify(e.message)}return}
if(form==='adminOfferForm'){try{const b={gameId:f.elements.gameId.value,provider:S.selectedProvider,productId:f.elements.productId.value,gainSm:Number(f.elements.gainSm.value)};const d=await adminAction('offer',b);notify('Oferta vinculada: '+d.product);await syncStore();route('/admin/offers')}catch(e){notify(e.message)}return}
if(form==='adminGameForm'){try{const fd=new FormData(f),b={id:fd.get('id'),name:fd.get('name'),category:fd.get('category'),imageUrl:fd.get('imageUrl'),featured:!!fd.get('featured'),sortOrder:fd.get('featured')?1:99};await adminAction('game',b);await syncStore();notify('Juego guardado en la base de datos.');route('/admin/offers')}catch(e){notify(e.message)}return}
if(form==='adminSettingsForm'){const fd=new FormData(f);const b={buySmPerUsdt:Number(fd.get('buySmPerUsdt')),cupPerSm:Number(fd.get('cupPerSm')),cardFee:Number(fd.get('cardFee')),mobilePhone:fd.get('mobilePhone'),walletPhone:fd.get('walletPhone'),cardNumber:fd.get('cardNumber'),confirmPhone:fd.get('confirmPhone'),planPrice:fd.get('planPrice')===''?null:Number(fd.get('planPrice')),planDays:Number(fd.get('planDays'))};try{await adminAction('settings',b);await syncStore();notify('Tasas y pagos sincronizados.');route('/admin/settings')}catch(e){notify(e.message)}return}
if(form==='adminFamilyForm'){if(!confirm('¿Publicar todos los productos disponibles de esta familia con la ganancia elegida?'))return;try{const r=await adminAction('import-family',{gameId:f.elements.gameId.value,familyId:f.elements.familyId.value,gainSm:Number(f.elements.gainSm.value)});await syncStore();await loadAdminAllOffers();notify('Importación: '+r.created+' nuevas y '+r.updated+' actualizadas.')}catch(e){notify(e.message)}return}
if(form==='adminCustomerEditForm'){try{await adminAction('customer-profile',{userId:f.elements.userId.value,fullName:f.elements.fullName.value,phone:f.elements.phone.value});$('modal').innerHTML='';await loadCustomers();notify('Perfil actualizado en Supabase.')}catch(e){notify(e.message)}return}
if(form==='adminOfferEditForm'){try{await adminAction('offer-edit',{id:f.elements.id.value,gainSm:Number(f.elements.gainSm.value),active:f.elements.active.checked});$('modal').innerHTML='';await syncStore();await loadAdminAllOffers();notify('Oferta actualizada.')}catch(e){notify(e.message)}return}
if(form==='adminOrderSearchForm'){S.admSearch=f.elements.q.value.trim().toUpperCase();loadAdminOrders();return}}
async function syncStore(){if(PREVIEW)return;const d=await api('/api/storefront');S.store=d;render()}
document.addEventListener('submit',e=>{if(!e.target.id)return;e.preventDefault();processForms(e.target)});
document.addEventListener('change',e=>{const t=e.target;if(t.id==='providerPicker'){S.selectedProvider=t.value;S.apiProducts=[];render();return}if(t.name==='payment'&&S.route==='/checkout'){S.payment=t.value;$('paymentDynamic').innerHTML=paymentFields();const sum=document.querySelector('.checkout-summary');if(sum)sum.outerHTML=sumBox();}if(t.id==='proofFile'&&t.files?.[0]){S.proofName=t.files[0].name;notify('Captura seleccionada: '+S.proofName)}});
document.addEventListener('input',e=>{if(e.target.id==='searchGames'){S.search=e.target.value;const pos=e.target.selectionStart;render();const i=$('searchGames');i?.focus();try{i.setSelectionRange(pos,pos)}catch{}}if(e.target.id==='orderSearch'){S.search=e.target.value;const pos=e.target.selectionStart;render();const i=$('orderSearch');i?.focus();try{i.setSelectionRange(pos,pos)}catch{}}});
document.addEventListener('click',async e=>{const t=e.target.closest('button,a,[data-href]');if(!t)return;
if(t.closest('[data-href]')&&t.dataset.href===undefined&&!t.hasAttribute('href')){const p=t.closest('[data-href]').dataset.href;if(p){route(p);return}}
const p=t.dataset.href||t.getAttribute('href');if(t.matches('[data-link]')||t.dataset.href){if(p&&p.startsWith('/')&&!p.startsWith('//')){e.preventDefault();route(p);return}}
if(t.id==='chooseRegister'){S.phoneRegister=true;render();return}if(t.id==='chooseLogin'){S.phoneRegister=false;render();return}
if(t.id==='splashRetry'){bootstrap();return}if(t.id==='startGoogle'){startGoogle();return}if(t.id==='logout'){try{await S.client?.auth.signOut();S.user=null;S.profile=null;S.wallet=null;S.member=false;route('/')}catch(e){notify(e.message)}return}
if(t.dataset.copy!==undefined){const str=t.dataset.copy;try{await navigator.clipboard.writeText(str);notify('Copiado correctamente')}catch{notify('No se pudo copiar. Mantén pulsado para seleccionar el dato.')}return}
if(t.dataset.buy){S.gameId=t.dataset.game;S.offerId=t.dataset.buy;try{sessionStorage.setItem('rs_v6_selected_offer',JSON.stringify({gameId:S.gameId,offerId:S.offerId}))}catch{}clearCheckout();route('/compra/datos');return}
if(t.dataset.step){const num=Number(t.dataset.step);route(checkoutPaths[num]||checkoutPaths[1]);return}
if(t.id==='sendOrder'){submitOrder();return}
if(t.dataset.filter){S.filter=t.dataset.filter;render();return}
if(t.dataset.detail){showDetail(t.dataset.detail,t.dataset.admin==='1');return}
if(t.id==='closeModal'){$('modal').innerHTML='';return}
if(t.dataset.adminStatus){changeOrderStatus(t.dataset.code,t.dataset.adminStatus);return}
if(t.id==='requestPlan'){doPlanRequest();return}
if(t.id==='logoutAdmin'){try{await api('/api/admin/logout',{method:'POST'});S.admin=false;S.customerScanInitialized=false;S.adminCustomers=[];route('/')}catch(e){notify(e.message)}return}
if(t.id==='loadProvider'){loadProvider();return}
if(t.id==='syncProvider'){try{const r=await adminAction('sync',{provider:S.selectedProvider});await syncStore();notify('Costos sincronizados. Ofertas actualizadas: '+r.updated)}catch(e){notify(e.message)}return}
if(t.id==='previewAdmin'&&PREVIEW){S.admin=true;S.adminCustomers=[];route('/admin');notify('Panel de muestra: operaciones administrativas desactivadas.');return}
if(t.dataset.contact){const c=S.adminCustomers.find(x=>x.id===t.dataset.customerId);if(!c)return;const url=manualContactUrl(c.phone,t.dataset.contact,c.name);if(!url){notify('Número de teléfono inválido');return}if(t.dataset.contact==='sms')window.location.href=url;else window.open(url,'_blank','noopener,noreferrer');notify('Se abrió el mensaje. Envíalo manualmente y luego marca al cliente como contactado.');return}
if(t.dataset.review){const c=S.adminCustomers.find(x=>x.id===t.dataset.customerId);if(!c)return;if(PREVIEW)return notify('En la vista previa no puedes confirmar registros.');if(t.dataset.review==='confirmed'&&!confirm('¿El cliente respondió personalmente que fue él quien se registró? Esto NO verifica la propiedad del teléfono.'))return;try{await adminAction('registration-review',{userId:c.id,status:t.dataset.review,channel:null});await loadCustomers();notify('Revisión administrativa guardada.')}catch(e){notify(e.message)}return}
if(t.id==='refreshCustomers'){loadCustomers();return}
if(t.id==='refreshFulfillments'){loadFulfillments();loadAdminOrders();return}
if(t.dataset.editCustomer){const c=S.adminCustomers.find(c=>c.id===t.dataset.editCustomer);if(!c)return;$('modal').innerHTML=`<div class="card modal-card" role="dialog" aria-modal="true"><div class="modal-head"><h2>Editar cliente</h2><button class="btn btn-ghost btn-sm" id="closeModal">Cerrar</button></div><form id="adminCustomerEditForm" class="fields mt2"><input type="hidden" name="userId" value="${esc(c.id)}"><div class="field"><label>Nombre</label><input name="fullName" value="${esc(c.name)}" maxlength="90" required></div><div class="field"><label>Teléfono internacional</label><input name="phone" maxlength="19" value="${esc(c.phone)}" required></div><button class="btn btn-primary btn-wide" type="submit">Guardar cliente</button></form></div>`;return}
if(t.dataset.editOffer){const o=S.adminAllOffers.find(o=>o.id===t.dataset.editOffer);if(!o){notify('Actualiza ofertas en ADM');return}$('modal').innerHTML=`<div class="card modal-card" role="dialog" aria-modal="true"><div class="modal-head"><h2>Editar oferta</h2><button class="btn btn-ghost btn-sm" id="closeModal">Cerrar</button></div><p>${esc(o.name)} · ${esc(o.provider_name)}</p><form id="adminOfferEditForm" class="fields mt2"><input type="hidden" name="id" value="${esc(o.id)}"><div class="field"><label>Ganancia en SM</label><input type="number" name="gainSm" min="0" step="0.01" required value="${esc(o.gain_sm)}"></div><label class="checkbox-line"><input type="checkbox" name="active" ${o.active?'checked':''}> Oferta publicada (si existe stock)</label><button class="btn btn-primary btn-wide" type="submit">Guardar oferta en Supabase</button></form></div>`;return}
if(t.dataset.fulfill){if(!confirm('¿Verificaste el pago real de '+t.dataset.fulfill+' y autorizas gastar saldo de Central One? Solo se envía una compra por pedido.'))return;try{const r=await adminAction('fulfill-order',{code:t.dataset.fulfill,paymentVerified:true});notify('Compra enviada al proveedor. Estado: '+(r.providerStatus||'confirmada'));await loadFulfillments();await loadAdminOrders()}catch(e){notify(e.message)}return}
if(t.dataset.reconcile){try{const r=await adminAction('reconcile-order',{orderId:t.dataset.reconcile});notify('Estado del proveedor: '+r.providerStatus);await loadFulfillments();await loadAdminOrders()}catch(e){notify(e.message)}return}
if(t.id==='reloadAdminOrders'){loadAdminOrders();return}
if(t.id==='refreshPlans'){loadPlanRequests();return}
if(t.dataset.approvePlan){planStatus(t.dataset.approvePlan,true);return}
if(t.dataset.rejectPlan){planStatus(t.dataset.rejectPlan,false);return}
if(t.dataset.deleteGame){if(!confirm('¿Eliminar este juego y sus ofertas vinculadas?'))return;try{await adminAction('delete-game',{id:t.dataset.deleteGame});await syncStore();notify('Juego eliminado.')}catch(e){notify(e.message)}return}
if(t.dataset.deleteOffer){if(!confirm('¿Eliminar esta oferta del catálogo?'))return;try{await adminAction('delete-offer',{id:t.dataset.deleteOffer});await syncStore();notify('Oferta eliminada.')}catch(e){notify(e.message)}return}
if(t.dataset.editGame){const g=game(t.dataset.editGame);if(!g)return;route('/admin/offers');const f=$('adminGameForm');f.elements.id.value=g.id;f.elements.name.value=g.name;f.elements.category.value=g.tag;f.elements.imageUrl.value=g.imageUrl||'';f.elements.featured.checked=!!g.featured;window.scrollTo({top:0});return}
});
document.addEventListener('keydown',e=>{if(e.key==='Escape')$('modal').innerHTML='' });
bootstrap();
})();